// Generated by CoffeeScript 1.10.0, ported to TypeScript for ticket 52.
//
// This is a vendored parser-combinator based URL pattern matcher. The AST produced
// by the parser is a dynamically tagged union (`{ tag: string, value: any }`) which
// isn't worth fully modelling for this conversion - the internals here are typed
// loosely with `any`/`unknown` as a deliberate, noted boundary. The public API
// (the `UrlPattern` class itself) is typed more precisely for consumers.

export type UrlPatternOptions = {
    escapeChar?: string;
    segmentNameStartChar?: string;
    segmentNameCharset?: string;
    segmentValueCharset?: string;
    optionalSegmentStartChar?: string;
    optionalSegmentEndChar?: string;
    wildcardChar?: string;
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AstNode = any;

type ParseResult<T> = { value: T; rest: string } | undefined;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Parser<T = any> = (input: string) => ParseResult<T>;

function escapeForRegex(string: string): string {
    return string.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&");
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function concatMap(array: any[], f: (item: any) => any): any[] {
    let results: any[] = [];
    let i = -1;
    const { length } = array;
    while (++i < length) {
        results = results.concat(f(array[i]));
    }
    return results;
}

function stringConcatMap(array: any[], f: (item: any) => string): string {
    let result = "";
    let i = -1;
    const { length } = array;
    while (++i < length) {
        result += f(array[i]);
    }
    return result;
}

function regexGroupCount(regex: RegExp): number {
    return new RegExp(`${regex.toString()}|`).exec("")!.length - 1;
}

function keysAndValuesToObject(
    keys: string[],
    values: any[]
): Record<string, any> {
    const object: Record<string, any> = {};
    let i = -1;
    const { length } = keys;
    while (++i < length) {
        const key = keys[i];
        const value = values[i];
        if (value == null) {
            continue;
        }
        if (object[key] != null) {
            if (!Array.isArray(object[key])) {
                object[key] = [object[key]];
            }
            object[key].push(value);
        } else {
            object[key] = value;
        }
    }
    return object;
}

// Parser combinators. `P.Result` / `P.Tagged` are plain value holders used
// throughout the recursive-descent parser below.
class PResult<T> {
    value: T;

    rest: string;

    constructor(value: T, rest: string) {
        this.value = value;
        this.rest = rest;
    }
}

class PTagged {
    tag: string;

    value: any;

    constructor(tag: string, value: any) {
        this.tag = tag;
        this.value = value;
    }
}

const P = {
    Result: PResult,
    Tagged: PTagged,

    tag(tag: string, parser: Parser): Parser<PTagged> {
        return (input: string) => {
            const result = parser(input);
            if (result == null) {
                return undefined;
            }
            const tagged = new PTagged(tag, result.value);
            return new PResult(tagged, result.rest);
        };
    },

    regex(regex: RegExp): Parser<string> {
        return (input: string) => {
            const matches = regex.exec(input);
            if (matches == null) {
                return undefined;
            }
            const result = matches[0];
            return new PResult(result, input.slice(result.length));
        };
    },

    sequence(...parsers: Parser[]): Parser<any[]> {
        return (input: string) => {
            let i = -1;
            const { length } = parsers;
            const values: any[] = [];
            let rest = input;
            while (++i < length) {
                const parser = parsers[i];
                const result = parser(rest);
                if (result == null) {
                    return undefined;
                }
                values.push(result.value);
                rest = result.rest;
            }
            return new PResult(values, rest);
        };
    },

    pick(indexes: number, ...parsers: Parser[]): Parser {
        return (input: string) => {
            const result = P.sequence(...parsers)(input);
            if (result == null) {
                return undefined;
            }
            const array = result.value;
            return new PResult(array[indexes], result.rest);
        };
    },

    string(string: string): Parser<string> {
        const { length } = string;
        return (input: string) => {
            if (input.slice(0, length) === string) {
                return new PResult(string, input.slice(length));
            }
            return undefined;
        };
    },

    lazy(fn: () => Parser): Parser {
        let cached: Parser | null = null;
        return (input: string) => {
            if (cached == null) {
                cached = fn();
            }
            return cached(input);
        };
    },

    baseMany(
        parser: Parser,
        end: Parser | null | undefined,
        stringResult: boolean,
        atLeastOneResultRequired: boolean,
        input: string
    ): ParseResult<any> {
        let rest = input;
        let results: any = stringResult ? "" : [];
        // eslint-disable-next-line no-constant-condition
        while (true) {
            if (end != null) {
                const endResult = end(rest);
                if (endResult != null) {
                    break;
                }
            }
            const parserResult = parser(rest);
            if (parserResult == null) {
                break;
            }
            if (stringResult) {
                results += parserResult.value;
            } else {
                results.push(parserResult.value);
            }
            rest = parserResult.rest;
        }
        if (atLeastOneResultRequired && results.length === 0) {
            return undefined;
        }
        return new PResult(results, rest);
    },

    many1(parser: Parser): Parser<any[]> {
        return (input: string) => P.baseMany(parser, null, false, true, input);
    },

    concatMany1Till(parser: Parser, end: Parser): Parser<string> {
        return (input: string) => P.baseMany(parser, end, true, true, input);
    },

    firstChoice(...parsers: Parser[]): Parser {
        return (input: string) => {
            let i = -1;
            const { length } = parsers;
            while (++i < length) {
                const parser = parsers[i];
                const result = parser(input);
                if (result != null) {
                    return result;
                }
            }
            return undefined;
        };
    }
};

type InternalOptions = Required<UrlPatternOptions>;

function newParser(options: InternalOptions) {
    const U: Record<string, Parser> = {};
    U.wildcard = P.tag("wildcard", P.string(options.wildcardChar));
    U.optional = P.tag(
        "optional",
        P.pick(
            1,
            P.string(options.optionalSegmentStartChar),
            P.lazy(() => U.pattern),
            P.string(options.optionalSegmentEndChar)
        )
    );
    U.name = P.regex(new RegExp(`^[${options.segmentNameCharset}]+`));
    U.namedWildcard = P.tag(
        "namedWildcard",
        P.pick(
            2,
            P.string(options.wildcardChar),
            P.string(options.segmentNameStartChar),
            P.lazy(() => U.name)
        )
    );
    U.named = P.tag(
        "named",
        P.pick(
            1,
            P.string(options.segmentNameStartChar),
            P.lazy(() => U.name)
        )
    );
    U.escapedChar = P.pick(1, P.string(options.escapeChar), P.regex(/^./));
    U.static = P.tag(
        "static",
        P.concatMany1Till(
            P.firstChoice(
                P.lazy(() => U.escapedChar),
                P.regex(/^./)
            ),
            P.firstChoice(
                P.string(options.segmentNameStartChar),
                P.string(options.optionalSegmentStartChar),
                P.string(options.optionalSegmentEndChar),
                U.wildcard
            )
        )
    );
    U.token = P.lazy(() =>
        P.firstChoice(U.namedWildcard, U.wildcard, U.optional, U.named, U.static)
    );
    U.pattern = P.many1(P.lazy(() => U.token));
    return U;
}

const defaultOptions: InternalOptions = {
    escapeChar: "\\",
    segmentNameStartChar: ":",
    segmentValueCharset: "a-zA-Z0-9-_~ %",
    segmentNameCharset: "a-zA-Z0-9",
    optionalSegmentStartChar: "(",
    optionalSegmentEndChar: ")",
    wildcardChar: "*"
};

function baseAstNodeToRegexString(
    astNode: AstNode,
    segmentValueCharset: string
): string {
    if (Array.isArray(astNode)) {
        return stringConcatMap(astNode, node =>
            baseAstNodeToRegexString(node, segmentValueCharset)
        );
    }
    switch (astNode.tag) {
        case "wildcard":
        case "namedWildcard":
            return "(.*?)";
        case "named":
            return `([${segmentValueCharset}]+)`;
        case "static":
            return escapeForRegex(astNode.value);
        case "optional":
            return `(?:${baseAstNodeToRegexString(
                astNode.value,
                segmentValueCharset
            )})?`;
        default:
            return "";
    }
}

function astNodeToRegexString(
    astNode: AstNode,
    segmentValueCharset: string = defaultOptions.segmentValueCharset
): string {
    return `^${baseAstNodeToRegexString(astNode, segmentValueCharset)}$`;
}

function astNodeToNames(astNode: AstNode): string[] {
    if (Array.isArray(astNode)) {
        return concatMap(astNode, astNodeToNames);
    }
    switch (astNode.tag) {
        case "wildcard":
            return ["_"];
        case "namedWildcard":
        case "named":
            return [astNode.value];
        case "static":
            return [];
        case "optional":
            return astNodeToNames(astNode.value);
        default:
            return [];
    }
}

function getParam(
    params: Record<string, any>,
    key: string,
    nextIndexes: Record<string, number>,
    sideEffects = false
): any {
    const value = params[key];
    if (value == null) {
        if (sideEffects) {
            throw new Error(`no values provided for key \`${key}\``);
        } else {
            return undefined;
        }
    }
    const index = nextIndexes[key] || 0;
    const maxIndex = Array.isArray(value) ? value.length - 1 : 0;
    if (index > maxIndex) {
        if (sideEffects) {
            throw new Error(`too few values provided for key \`${key}\``);
        } else {
            return undefined;
        }
    }
    const result = Array.isArray(value) ? value[index] : value;
    if (sideEffects) {
        nextIndexes[key] = index + 1;
    }
    return result;
}

function astNodeContainsSegmentsForProvidedParams(
    astNode: AstNode,
    params: Record<string, any>,
    nextIndexes: Record<string, number>
): boolean {
    if (Array.isArray(astNode)) {
        let i = -1;
        const { length } = astNode;
        while (++i < length) {
            if (
                astNodeContainsSegmentsForProvidedParams(
                    astNode[i],
                    params,
                    nextIndexes
                )
            ) {
                return true;
            }
        }
        return false;
    }
    switch (astNode.tag) {
        case "wildcard":
            return getParam(params, "_", nextIndexes, false) != null;
        case "named":
            return getParam(params, astNode.value, nextIndexes, false) != null;
        case "static":
            return false;
        case "optional":
            return astNodeContainsSegmentsForProvidedParams(
                astNode.value,
                params,
                nextIndexes
            );
        default:
            return false;
    }
}

function stringifyAst(
    astNode: AstNode,
    params: Record<string, any>,
    nextIndexes: Record<string, number>
): string {
    if (Array.isArray(astNode)) {
        return stringConcatMap(astNode, node =>
            stringifyAst(node, params, nextIndexes)
        );
    }
    switch (astNode.tag) {
        case "wildcard":
            return getParam(params, "_", nextIndexes, true);
        case "named":
        case "namedWildcard":
            return getParam(params, astNode.value, nextIndexes, true);
        case "static":
            return astNode.value;
        case "optional":
            if (
                astNodeContainsSegmentsForProvidedParams(
                    astNode.value,
                    params,
                    nextIndexes
                )
            ) {
                return stringifyAst(astNode.value, params, nextIndexes);
            }
            return "";
        default:
            return "";
    }
}

/**
 * Parses a path pattern such as `/foo/:bar` and provides `match`/`stringify`
 * methods to convert between URL strings and captured parameter objects.
 */
class UrlPattern {
    isRegex: boolean;

    regex!: RegExp;

    ast?: AstNode;

    names?: string[];

    constructor(pattern: string | RegExp | UrlPattern, options?: UrlPatternOptions | string[]) {
        if (pattern instanceof UrlPattern) {
            this.isRegex = pattern.isRegex;
            this.regex = pattern.regex;
            this.ast = pattern.ast;
            this.names = pattern.names;
            return;
        }
        this.isRegex = pattern instanceof RegExp;
        if (!(typeof pattern === "string" || this.isRegex)) {
            throw new TypeError("argument must be a regex or a string");
        }
        if (this.isRegex) {
            this.regex = pattern as RegExp;
            if (options != null) {
                if (!Array.isArray(options)) {
                    throw new Error(
                        "if first argument is a regex the second argument may be an array of group names but you provided something else"
                    );
                }
                const groupCount = regexGroupCount(this.regex);
                if (options.length !== groupCount) {
                    throw new Error(
                        `regex contains ${groupCount} groups but array of group names contains ${options.length}`
                    );
                }
                this.names = options;
            }
            return;
        }
        const arg1 = pattern as string;
        const arg2 = options as UrlPatternOptions | undefined;
        if (arg1 === "") {
            throw new Error("argument must not be the empty string");
        }
        const withoutWhitespace = arg1.replace(/\s+/g, "");
        if (withoutWhitespace !== arg1) {
            throw new Error("argument must not contain whitespace");
        }
        const resolvedOptions: InternalOptions = {
            escapeChar: arg2?.escapeChar || defaultOptions.escapeChar,
            segmentNameStartChar:
                arg2?.segmentNameStartChar || defaultOptions.segmentNameStartChar,
            segmentNameCharset:
                arg2?.segmentNameCharset || defaultOptions.segmentNameCharset,
            segmentValueCharset:
                arg2?.segmentValueCharset || defaultOptions.segmentValueCharset,
            optionalSegmentStartChar:
                arg2?.optionalSegmentStartChar ||
                defaultOptions.optionalSegmentStartChar,
            optionalSegmentEndChar:
                arg2?.optionalSegmentEndChar ||
                defaultOptions.optionalSegmentEndChar,
            wildcardChar: arg2?.wildcardChar || defaultOptions.wildcardChar
        };
        const parser = newParser(resolvedOptions);
        const parsed = parser.pattern(arg1);
        if (parsed == null) {
            throw new Error("couldn't parse pattern");
        }
        if (parsed.rest !== "") {
            throw new Error("could only partially parse pattern");
        }
        this.ast = parsed.value;
        this.regex = new RegExp(
            astNodeToRegexString(this.ast, resolvedOptions.segmentValueCharset)
        );
        this.names = astNodeToNames(this.ast);
    }

    match(url: string): Record<string, any> | any[] | null {
        const match = this.regex.exec(url);
        if (match == null) {
            return null;
        }
        const groups = match.slice(1);
        if (this.names) {
            return keysAndValuesToObject(this.names, groups);
        }
        return groups;
    }

    stringify(params: Record<string, any> = {}): string {
        if (this.isRegex) {
            throw new Error("can't stringify patterns generated from a regex");
        }
        if (params !== Object(params)) {
            throw new Error("argument must be an object or undefined");
        }
        return stringifyAst(this.ast, params, {});
    }

    static escapeForRegex = escapeForRegex;

    static concatMap = concatMap;

    static stringConcatMap = stringConcatMap;

    static regexGroupCount = regexGroupCount;

    static keysAndValuesToObject = keysAndValuesToObject;

    static P = P;

    static newParser = newParser;

    static defaultOptions = defaultOptions;

    static astNodeToRegexString = astNodeToRegexString;

    static astNodeToNames = astNodeToNames;

    static getParam = getParam;

    static astNodeContainsSegmentsForProvidedParams = astNodeContainsSegmentsForProvidedParams;

    static stringify = stringifyAst;
}

export default UrlPattern;
